45	/**
46	 * A Zookeeper-based implementation of {@link YarnConfigurationStore}.
47	 */
48	public class ZKConfigurationStore extends YarnConfigurationStore {
49	
50	  public static final Logger LOG =
51	      LoggerFactory.getLogger(ZKConfigurationStore.class);
52	
53	  private long maxLogs;
54	
55	  @VisibleForTesting
56	  protected static final Version CURRENT_VERSION_INFO = Version
57	      .newInstance(0, 1);
58	  private Configuration conf;
59	
60	  private static final String ZK_VERSION_PATH = "VERSION";
61	  private static final String LOGS_PATH = "LOGS";
62	  private static final String CONF_STORE_PATH = "CONF_STORE";
63	  private static final String FENCING_PATH = "FENCING";
64	  private static final String CONF_VERSION_PATH = "CONF_VERSION";
65	  private static final String NODEEXISTS_MSG = "Encountered NodeExists error."
66	      + " Skipping znode creation since another RM has already created it";
67	  private String zkVersionPath;
68	  private String logsPath;
69	  private String confStorePath;
70	  private String fencingNodePath;
71	  private String confVersionPath;
72	
73	  private ZKCuratorManager zkManager;
74	  private List<ACL> zkAcl;
75	
76	  @Override
77	  public void initialize(Configuration config, Configuration schedConf,
78	      RMContext rmContext) throws Exception {
79	    this.conf = config;
80	
81	    String znodeParentPath = conf.get(
82	        YarnConfiguration.RM_SCHEDCONF_STORE_ZK_PARENT_PATH,
83	        YarnConfiguration.DEFAULT_RM_SCHEDCONF_STORE_ZK_PARENT_PATH);
84	
85	    this.maxLogs = conf.getLong(YarnConfiguration.RM_SCHEDCONF_MAX_LOGS,
86	        YarnConfiguration.DEFAULT_RM_SCHEDCONF_ZK_MAX_LOGS);
87	    this.zkManager =
88	        rmContext.getResourceManager().createAndStartZKManager(conf);
89	    this.zkAcl = ZKCuratorManager.getZKAcls(conf);
90	
91	    this.zkVersionPath = getNodePath(znodeParentPath, ZK_VERSION_PATH);
92	    this.logsPath = getNodePath(znodeParentPath, LOGS_PATH);
93	    this.confStorePath = getNodePath(znodeParentPath, CONF_STORE_PATH);
94	    this.fencingNodePath = getNodePath(znodeParentPath, FENCING_PATH);
95	    this.confVersionPath = getNodePath(znodeParentPath, CONF_VERSION_PATH);
96	
97	    try {
98	      zkManager.createRootDirRecursively(znodeParentPath, zkAcl);
99	    } catch(NodeExistsException e) {
100	      LOG.warn(NODEEXISTS_MSG, e);
101	    }
102	    zkManager.delete(fencingNodePath);
103	
104	    if (createNewZkPath(logsPath)) {
105	      setZkData(logsPath, new LinkedList<LogMutation>());
106	    }
107	
108	    if (createNewZkPath(confVersionPath)) {
109	      setZkData(confVersionPath, String.valueOf(0));
110	    }
111	
112	    if (createNewZkPath(confStorePath)) {
113	      HashMap<String, String> mapSchedConf = new HashMap<>();
114	      for (Map.Entry<String, String> entry : schedConf) {
115	        mapSchedConf.put(entry.getKey(), entry.getValue());
116	      }
117	      setZkData(confStorePath, mapSchedConf);
118	      long configVersion = getConfigVersion() + 1L;
119	      setZkData(confVersionPath, String.valueOf(configVersion));
120	    }
121	  }
122	
123	  @VisibleForTesting
124	  @Override
125	  protected LinkedList<LogMutation> getLogs() throws Exception {
126	    return unsafeCast(deserializeObject(getZkData(logsPath)));
127	  }
128	
129	  @Override
130	  public Version getCurrentVersion() {
131	    return CURRENT_VERSION_INFO;
132	  }
133	
134	  @Override
135	  public Version getConfStoreVersion() throws Exception {
136	    if (zkManager.exists(zkVersionPath)) {
137	      byte[] data = getZkData(zkVersionPath);
138	      return new VersionPBImpl(YarnServerCommonProtos.VersionProto
139	          .parseFrom(data));
140	    }
141	
142	    return null;
143	  }
144	
145	  @Override
146	  public void format() throws Exception {
147	    zkManager.delete(confStorePath);
148	  }
149	
150	  @Override
151	  public synchronized void storeVersion() throws Exception {
152	    byte[] data =
153	        ((VersionPBImpl) CURRENT_VERSION_INFO).getProto().toByteArray();
154	
155	    if (zkManager.exists(zkVersionPath)) {
156	      safeSetZkData(zkVersionPath, data);
157	    } else {
158	      safeCreateZkData(zkVersionPath, data);
159	    }
160	  }
161	
162	  @Override
163	  public void logMutation(LogMutation logMutation) throws Exception {
164	    if (maxLogs > 0) {
165	      byte[] storedLogs = getZkData(logsPath);
166	      LinkedList<LogMutation> logs = new LinkedList<>();
167	      if (storedLogs != null) {
168	        logs = unsafeCast(deserializeObject(storedLogs));
169	      }
170	      logs.add(logMutation);
171	      if (logs.size() > maxLogs) {
172	        logs.remove(logs.removeFirst());
173	      }
174	      safeSetZkData(logsPath, logs);
175	    }
176	  }
177	
178	  @Override
179	  public void confirmMutation(LogMutation pendingMutation,
180	      boolean isValid) throws Exception {
181	    if (isValid) {
182	      Configuration storedConfigs = retrieve();
183	      Map<String, String> mapConf = new HashMap<>();
184	      for (Map.Entry<String, String> storedConf : storedConfigs) {
185	        mapConf.put(storedConf.getKey(), storedConf.getValue());
186	      }
187	      for (Map.Entry<String, String> confChange :
188	          pendingMutation.getUpdates().entrySet()) {
189	        if (confChange.getValue() == null || confChange.getValue().isEmpty()) {
190	          mapConf.remove(confChange.getKey());
191	        } else {
192	          mapConf.put(confChange.getKey(), confChange.getValue());
193	        }
194	      }
195	      safeSetZkData(confStorePath, mapConf);
196	      long configVersion = getConfigVersion() + 1L;
197	      setZkData(confVersionPath, String.valueOf(configVersion));
198	
199	    }
200	  }
201	
202	  @Override
203	  public synchronized Configuration retrieve() {
204	    byte[] serializedSchedConf;
205	    try {
206	      serializedSchedConf = getZkData(confStorePath);
207	    } catch (Exception e) {
208	      LOG.error("Failed to retrieve configuration from zookeeper store", e);
209	      return null;
210	    }
211	    try {
212	      Map<String, String> map =
213	          unsafeCast(deserializeObject(serializedSchedConf));
214	      Configuration c = new Configuration(false);
215	      for (Map.Entry<String, String> e : map.entrySet()) {
216	        c.set(e.getKey(), e.getValue());
217	      }
218	      return c;
219	    } catch (Exception e) {
220	      LOG.error("Exception while deserializing scheduler configuration " +
221	          "from store", e);
222	    }
223	    return null;
224	  }
225	
226	  @Override
227	  public long getConfigVersion() throws Exception {
228	    String version = zkManager.getStringData(confVersionPath);
229	    if (version == null) {
230	      throw new IllegalStateException("Config version can not be properly " +
231	          "serialized. Check Zookeeper config version path to locate " +
232	          "the error!");
233	    }
234	
235	    return Long.parseLong(version);
236	  }
237	
238	  @Override
239	  public List<LogMutation> getConfirmedConfHistory(long fromId) {
240	    return null; // unimplemented
241	  }
242	
243	  /**
244	   * Creates a new path in Zookeeper only, if it does not already exist.
245	   *
246	   * @param path Value of the Zookeeper path
247	   * @return <code>true</code>if the creation executed; <code>false</code>
248	   * otherwise.
249	   * @throws Exception
250	   */
251	  private boolean createNewZkPath(String path) throws Exception {
252	    if (!zkManager.exists(path)) {
253	      try {
254	        zkManager.create(path);
255	      } catch(NodeExistsException e) {
256	        LOG.warn(NODEEXISTS_MSG, e);
257	        return false;
258	      }
259	      return true;
260	    } else {
261	      return false;
262	    }
263	  }
264	
265	  @VisibleForTesting
266	  protected byte[] getZkData(String path) throws Exception {
267	    return zkManager.getData(path);
268	  }
269	
270	  @VisibleForTesting
271	  protected void setZkData(String path, byte[] data) throws Exception {
272	    zkManager.setData(path, data, -1);
273	  }
274	
275	  private void setZkData(String path, Object data) throws Exception {
276	    setZkData(path, serializeObject(data));
277	  }
278	
279	  private void setZkData(String path, String data) throws Exception {
280	    zkManager.setData(path, data, -1);
281	  }
282	
283	  private void safeSetZkData(String path, byte[] data) throws Exception {
284	    zkManager.safeSetData(path, data, -1, zkAcl, fencingNodePath);
285	  }
286	
287	  private void safeSetZkData(String path, Object data) throws Exception {
288	    safeSetZkData(path, serializeObject(data));
289	  }
290	
291	  @VisibleForTesting
292	  protected void safeCreateZkData(String path, byte[] data) throws Exception {
293	    try {
294	      zkManager.safeCreate(path, data, zkAcl, CreateMode.PERSISTENT,
295	          zkAcl, fencingNodePath);
296	    } catch(NodeExistsException e) {
297	      LOG.warn(NODEEXISTS_MSG, e);
298	    }
299	  }
300	
301	  private static String getNodePath(String root, String nodeName) {
302	    return ZKCuratorManager.getNodePath(root, nodeName);
303	  }
304	
305	  private static byte[] serializeObject(Object o) throws Exception {
306	    try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
307	        ObjectOutputStream oos = new ObjectOutputStream(baos);) {
308	      oos.writeObject(o);
309	      oos.flush();
310	      baos.flush();
311	      return baos.toByteArray();
312	    }
313	  }
314	
315	  private static Object deserializeObject(byte[] bytes) throws Exception {
316	    try (ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
317	        ObjectInputStream ois = new ObjectInputStream(bais);) {
318	      return ois.readObject();
319	    }
320	  }
321	
322	  /**
323	   * Casts an object of type Object to type T. It is essential to emphasize,
324	   * that it is an unsafe operation.
325	   *
326	   * @param o Object to be cast from
327	   * @param <T> Type to cast to
328	   * @return casted object of type T
329	   * @throws ClassCastException
330	   */
331	  @SuppressWarnings("unchecked")
332	  private static <T> T unsafeCast(Object o) throws ClassCastException {
333	    return (T)o;
334	  }
335	
336	  @Override
337	  public void close() throws IOException {
338	    if (zkManager  != null) {
339	      zkManager.close();
340	    }
341	  }
342	}

